            code = gs_note_error(gs_error_rangecheck);
            goto done;
        }
        memcpy(ctx->encryption.O, s->data, 32);
    } else {
        if (s->length < 48) {
            code = gs_note_error(gs_error_rangecheck);
            goto done;
        }
        memcpy(ctx->encryption.O, s->data, 48);
    }
    pdfi_countdown(s);
    s = NULL;

    code = pdfi_dict_get_type(ctx, d, "U", PDF_STRING, (pdf_obj **)&s);
    if (code < 0)
        goto done;

    if (ctx->encryption.R < 5) {
        if (s->length < 32) {
            code = gs_note_error(gs_error_rangecheck);
