    int code = 0, i, j, KeyLenBytes = KeyLen / 8;
    pdf_c_stream *stream, *arc4_stream;
    char Buffer[32];
    char Hash[16];
    gs_md5_state_t md5;
    pdf_string *s = NULL;
    pdf_array *a = NULL;

